const supersedeDeletedMultipartUploads = `-- name: SupersedeDeletedMultipartUploads :exec
UPDATE s3_multipart_uploads SET superseded = true
WHERE s3_multipart_uploads.partition = ?1 AND s3_multipart_uploads.bucket_name = ?2 AND s3_multipart_uploads.object_name = ?3
AND (
    ?4 = (
        SELECT v.version_id FROM s3_object_versions AS v
        WHERE v.partition = ?1 AND v.bucket_name = ?2 AND v.name = ?3
        ORDER BY v.created_order DESC LIMIT 1
    )
    OR (
        CAST(?4 AS TEXT) = 'null'
        AND NOT EXISTS (
            SELECT 1 FROM s3_object_versions AS v
            WHERE v.partition = ?1 AND v.bucket_name = ?2
            AND v.name = ?3 AND v.version_id = 'null'
        )
        AND EXISTS (
            SELECT 1 FROM s3_buckets AS b
            WHERE b.partition = ?1 AND b.name = ?2 AND b.versioning = ''
        )
    )
)
`

type SupersedeDeletedMultipartUploadsParams struct {
	Partition  string
	BucketName string
	ObjectName string
	VersionID  string
}

func (q *Queries) SupersedeDeletedMultipartUploads(ctx context.Context, arg SupersedeDeletedMultipartUploadsParams) error {
	_, err := q.db.ExecContext(ctx, supersedeDeletedMultipartUploads,
		arg.Partition,
		arg.BucketName,
		arg.ObjectName,
		arg.VersionID,
	)
	return err
}

